package at.hausgarten.service;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Synthetic HTTPS responses only. No account, network, Android runtime or operational data. */
public final class DriveTransportTests {
    interface Case{void run()throws Exception;}static int passed;
    static void check(String name,Case c)throws Exception{c.run();passed++;System.out.println("PASS "+name);}
    static void yes(boolean b){if(!b)throw new AssertionError();}
    static void reject(Case c)throws Exception{try{c.run();}catch(Exception e){return;}throw new AssertionError("Expected failure");}
    static DriveRestClient.Reply reply(int code,String body){return new DriveRestClient.Reply(code,body.getBytes(StandardCharsets.UTF_8),new HashMap<>());}
    static final class Memory implements DriveRestClient.Checkpoints{Map<String,String> values=new HashMap<>();public String get(String key){return values.getOrDefault(key,"");}public void put(String key,String v){values.put(key,v);}}
    static final class Remote implements DriveRestClient.Wire{
        byte[] original,stored;int offset,puts,starts,reads;boolean failSecond,corrupt;String token;Remote(byte[] data){original=data;}
        public DriveRestClient.Reply send(String method,String url,Map<String,String> hs,byte[] body,int maximum)throws Exception{
            token=hs.get("Authorization");
            if(method.equals("GET")&&url.contains("files?q="))return reply(200,SyntheticBusinessData.object().put("files",stored==null?new JSONArray():new JSONArray().put(SyntheticBusinessData.object().put("id","qa_file_synthetic_001").put("name","sample.json").put("version","1").put("md5Checksum","synthetic").put("size",stored.length))).toString());
            if(method.equals("POST")){starts++;return new DriveRestClient.Reply(200,new byte[0],Collections.singletonMap("Location","https://www.googleapis.com/upload/drive/v3/files?upload_id=synthetic"));}
            if(method.equals("GET")){reads++;return new DriveRestClient.Reply(200,corrupt?new byte[]{0}:stored,new HashMap<>());}
            if(body.length==0){if(stored!=null)return reply(200,"{\"id\":\"qa_file_synthetic_001\"}");return new DriveRestClient.Reply(308,new byte[0],offset==0?new HashMap<>():Collections.singletonMap("Range","bytes=0-"+(offset-1)));}
            puts++;if(failSecond&&puts==2)throw new IOException("synthetic interruption");yes(hs.get("Content-Range").startsWith("bytes "+offset+"-"));offset+=body.length;
            if(offset==original.length){stored=original;return reply(200,"{\"id\":\"qa_file_synthetic_001\"}");}return new DriveRestClient.Reply(308,new byte[0],Collections.singletonMap("Range","bytes=0-"+(offset-1)));
        }
    }
    static DriveRestClient client(DriveRestClient.Wire wire,Memory m){return new DriveRestClient("folder_synthetic_001",()->"synthetic-test-only",wire,m);}
    public static void main(String[] args)throws Exception{ SyntheticBusinessData.verify();
        check("folder links select only valid Google folder identifiers",()->{yes(DriveRestClient.folderId("https://drive.google.com/drive/folders/folder_synthetic_001?x=1").equals("folder_synthetic_001"));reject(()->DriveRestClient.folderId("https://foreign.invalid/folder"));reject(()->DriveRestClient.folderId("../bad"));});
        check("retry-after seconds, dates and malformed values bounded",()->{yes(DriveRestClient.retryAfter("120")==120000);yes(DriveRestClient.retryAfter("99999999")==3600000);yes(DriveRestClient.retryAfter("bad")==30000);yes(DriveRestClient.retryAfter("Sun, 18 Oct 2026 12:00:00 GMT")>=1000);});
        check("resumable upload server proof and immutable replay",()->{byte[] b=new byte[600000];Arrays.fill(b,(byte)7);Remote remote=new Remote(b);Memory m=new Memory();DriveRestClient c=client(remote,m);c.put(c.folder,"sample.json","application/json",b);yes(remote.puts==3&&remote.starts==1&&remote.reads==1);c.put(c.folder,"sample.json","application/json",b);yes(remote.starts==1&&remote.reads==2&&m.values.entrySet().stream().filter(e->e.getKey().startsWith("drive-upload:")).allMatch(e->e.getValue().isEmpty()));});
        check("process interruption resumes existing upload without duplicate",()->{byte[] b=new byte[600000];Remote remote=new Remote(b);remote.failSecond=true;Memory m=new Memory();DriveRestClient c=client(remote,m);reject(()->c.put(c.folder,"sample.json","application/json",b));yes(remote.offset==DriveRestClient.CHUNK&&remote.starts==1);remote.failSecond=false;client(remote,m).put(c.folder,"sample.json","application/json",b);yes(remote.offset==b.length&&remote.starts==1);});
        check("different immutable bytes are never overwritten",()->{Remote r=new Remote(new byte[]{1,2});r.stored=r.original;reject(()->client(r,new Memory()).put("folder_synthetic_001","sample.json","application/json",new byte[]{3}));yes(r.starts==0&&r.puts==0);});
        check("readback mismatch never records completed upload",()->{Remote r=new Remote(new byte[]{1,2});r.corrupt=true;Memory m=new Memory();reject(()->client(r,m).put("folder_synthetic_001","sample.json","application/json",r.original));yes(m.values.values().stream().anyMatch(s->!s.isEmpty()));});
        check("expired authentication is not retried or bypassed",()->{int[] calls={0};try{client((method,url,h,b,max)->{calls[0]++;return reply(401,"");},new Memory()).list("folder_synthetic_001");throw new AssertionError();}catch(DriveRestClient.Failure e){yes(e.userAction&&e.code.equals("AUTH_REQUIRED")&&calls[0]==1);}});
        check("revoked folder permissions require device action",()->{try{client((a,b,c,d,e)->reply(403,""),new Memory()).validateFolder();throw new AssertionError();}catch(DriveRestClient.Failure e){yes(e.userAction&&e.code.equals("PERMISSION_REQUIRED"));}});
        check("429 honors retry-after without busy looping",()->{try{client((a,b,c,d,e)->new DriveRestClient.Reply(429,new byte[0],Collections.singletonMap("Retry-After","60")),new Memory()).list("folder_synthetic_001");throw new AssertionError();}catch(DriveRestClient.Failure e){yes(!e.userAction&&e.retryAfter==60000);}});
        check("missing folder capability fails closed",()->reject(()->client((a,b,c,d,e)->reply(200,"{\"mimeType\":\"application/vnd.google-apps.folder\"}"),new Memory()).validateFolder()));
        check("missing token issues no HTTP request",()->{int[] calls={0};DriveRestClient c=new DriveRestClient("folder_synthetic_001",()->"",(a,b,h,d,e)->{calls[0]++;return reply(200,"");},new Memory());reject(()->c.list(c.folder));yes(calls[0]==0);});
        check("untrusted upload redirect never receives a token",()->{int[] calls={0};DriveRestClient c=client((method,url,h,b,max)->{calls[0]++;return method.equals("GET")?reply(200,"{\"files\":[]}"):new DriveRestClient.Reply(200,new byte[0],Collections.singletonMap("Location","https://foreign.invalid/upload"));},new Memory());reject(()->c.put(c.folder,"sample.json","application/json",new byte[]{1}));yes(calls[0]==2);});
        check("server version proof avoids repeated original downloads",()->{Remote r=new Remote(new byte[]{1,2});r.stored=r.original;Memory m=new Memory();DriveRestClient c=client(r,m);c.confirm(c.folder,"sample.json",DriveRestClient.sha256(r.original),100);c.confirm(c.folder,"sample.json",DriveRestClient.sha256(r.original),100);yes(r.reads==1);});
        check("manifest binds snapshot and action content",()->{JSONObject s=DriveJournalTests.snapshot();JSONObject a=DriveJournalTests.action("request-1","worklog",DriveJournalTests.work("qa_w"));JSONArray actions=new JSONArray().put(a);DriveJournalRules.apply(s,actions);byte[] bytes=DrivePublication.stateBytes(s);JSONObject m=DrivePublication.manifest(s,actions,"qa_file_synthetic_001",DriveRestClient.sha256(bytes));DrivePublication.verify(m,bytes,actions);yes(m.getJSONObject("receipts").getJSONObject("request-1").getBoolean("applied"));reject(()->DrivePublication.verify(m,new byte[]{0},actions));a.getJSONObject("payload").put("hours",5);reject(()->DrivePublication.verify(m,bytes,actions));});
        check("deferred invoice cannot receive a fabricated application receipt",()->{JSONObject s=DriveJournalTests.snapshot(),a=DriveJournalTests.action("issue-1","owner_invoice_issue",SyntheticBusinessData.object().put("id","qa_i"));JSONArray actions=new JSONArray().put(a);DriveJournalRules.apply(s,actions);JSONObject m=DrivePublication.manifest(s,actions,"qa_file_synthetic_001",DriveRestClient.sha256(DrivePublication.stateBytes(s)));yes(!m.getJSONObject("receipts").getJSONObject("issue-1").getBoolean("applied"));});
        check("provider-only state stays unconfirmed",()->{JSONObject result=DrivePublication.evidence(SyntheticBusinessData.object().put("client_id","x").put("cloud_confirmed",false),SyntheticBusinessData.object().put("master",DriveJournalTests.snapshot()));yes(!result.getBoolean("cloud_confirmed"));});
        check("customer prerequisites precede an earlier-clock work action",()->{JSONObject c=DriveJournalTests.action("new-c","customer",SyntheticBusinessData.object().put("id","qa_c2").put("name","Zweiter Kunde").put("_mcp_create",true));JSONObject w=DriveJournalTests.action("new-w","worklog",DriveJournalTests.work("qa_w").put("customer_id","qa_c2"));JSONArray all=new JSONArray().put(w).put(c);yes(SyncActionOrder.order(all).getJSONObject(0).getString("client_id").equals("new-c"));JSONObject s=DriveJournalTests.snapshot();yes(DriveJournalRules.apply(s,all).length()==0&&s.getJSONArray("worklogs").length()==1);});
        check("predecessor cycles retain all actions and reject",()->{JSONObject a=DriveJournalTests.action("a","customer",SyntheticBusinessData.object().put("_sync_predecessors",new JSONArray().put("b"))),b=DriveJournalTests.action("b","customer",SyntheticBusinessData.object().put("_sync_predecessors",new JSONArray().put("a")));reject(()->SyncActionOrder.order(new JSONArray().put(a).put(b)));yes(a.getJSONObject("payload").has("_sync_predecessors"));});
        check("disjoint edits preserve synchronized note",()->{JSONObject base=SyntheticBusinessData.object().put("id","qa_c1").put("name","Test").put("notes","alt").put("updated_at","t1"),current=SyntheticBusinessData.object(base.toString()).put("notes","Remote").put("updated_at","t2"),patch=SyntheticBusinessData.object(base.toString()).put("name","Neu").put("updated_at","t3");JSONObject m=SyncActionOrder.merge(base,patch,current,"customer");yes(m.getString("notes").equals("Remote")&&m.getString("name").equals("Neu"));patch.put("notes","Lokal");reject(()->SyncActionOrder.merge(base,patch,current,"customer"));});
        check("unknown garden area stays null and optional hints typed",()->{JSONObject c=SyntheticBusinessData.object().put("garden_area","").put("custom_fields",SyntheticBusinessData.object().put("Fremdes Feld","erhalten").put(GardenRules.LAWN,"12,5"));GardenRules.normalize(c);yes(c.isNull("garden_area")&&c.getJSONObject("custom_fields").getDouble(GardenRules.LAWN)==12.5&&c.getJSONObject("custom_fields").getString("Fremdes Feld").equals("erhalten"));reject(()->GardenRules.normalize(SyntheticBusinessData.object().put("garden_area",-1)));reject(()->GardenRules.normalize(SyntheticBusinessData.object().put("garden_area",10).put("custom_fields",SyntheticBusinessData.object().put(GardenRules.LAWN,20))));});
        check("publication recovery follows confirmed chain after process restart",()->{JSONObject a=SyntheticBusinessData.object().put("id","qa_commit1").put("publisher","pixel").put("sequence",1).put("sha","sha1").put("parent",""),b=SyntheticBusinessData.object().put("id","qa_commit2").put("publisher","pixel").put("sequence",2).put("sha","sha2").put("parent","qa_commit1").put("parent_sha","sha1");yes(DrivePublication.head(new JSONArray().put(b).put(a),"pixel").getString("id").equals("qa_commit2"));reject(()->DrivePublication.head(new JSONArray().put(b),"pixel"));reject(()->DrivePublication.head(new JSONArray().put(a).put(SyntheticBusinessData.object(b.toString()).put("publisher","other")),"pixel"));reject(()->DrivePublication.head(new JSONArray().put(a).put(SyntheticBusinessData.object(a.toString()).put("id","qa_fork")),"pixel"));});
        check("unknown area and explicit zero are different comparison versions",()->{reject(()->DriveJournalRules.compare(SyntheticBusinessData.object().put("id","qa_c").put("garden_area",JSONObject.NULL),SyntheticBusinessData.object().put("id","qa_c").put("garden_area",0)));});
        check("legacy delete requires an explicit guarded archive decision",()->{JSONObject s=DriveJournalTests.snapshot(),prior=DriveJournalTests.action("old-delete","delete",SyntheticBusinessData.object().put("entity","customer").put("id","qa_c1"));JSONArray a=new JSONArray().put(prior);yes(DriveJournalRules.apply(s,a).length()==1);s.put("drive_review_actions",DriveJournalRules.reviewActions(s,a));JSONObject c=PixelMcpOwnerTools.conflicts(SyntheticBusinessData.object().put("master",s).put("pending",a),SyntheticBusinessData.object()).getJSONArray("conflicts").getJSONObject(0);JSONObject p=SyntheticBusinessData.object().put("client_id","old-delete").put("expected_action_hash",c.getString("action_hash")).put("expected_current_hash",c.getString("current_hash")).put("resolution","apply_proposed");a.put(DriveJournalTests.action("review-old-delete","conflict_resolution",p));yes(DriveJournalRules.apply(s,a).length()==0);yes(s.getJSONArray("customers").getJSONObject(0).getInt("active")==0&&s.getJSONObject("owner_archive").getJSONObject("customer:qa_c1").getJSONObject("record").getString("name").equals("Test Kunde"));yes(s.getJSONObject("owner_conflict_history").getJSONObject("old-delete").has("original_action"));yes(DriveJournalRules.apply(s,a).length()==0);});
        check("job interruption stops before another HTTP request",()->{int[] calls={0};try{Thread.currentThread().interrupt();reject(()->client((a,b,c,d,e)->{calls[0]++;return reply(200,"{}");},new Memory()).list("folder_synthetic_001"));yes(calls[0]==0);}finally{Thread.interrupted();}});
        System.out.println(passed+" Drive transport/dependency/garden checks passed");
    }
}
